# Задание №3: эталонное решение на Python (pandas). Запуск: python solve.py файл.xlsx запрос.json
# Запрос — JSON с полями db (sweets|theatre|family), kind и параметрами вопроса (см. tests/*.json).
import sys, json
import pandas as pd


def sweets(path, q):
    mv = pd.read_excel(path, sheet_name="Движение товаров")
    pr = pd.read_excel(path, sheet_name="Товар")
    sh = pd.read_excel(path, sheet_name="Магазин")
    mv.columns = ["id", "date", "shop", "art", "packs", "type"]
    df = mv.merge(sh, left_on="shop", right_on="ID магазина").merge(pr, left_on="art", right_on="Артикул")
    df["date"] = pd.to_datetime(df["date"])
    m = (df["date"] >= q["d1"]) & (df["date"] <= q["d2"])                       # период включительно
    if q["loc"]["type"] == "district":
        m &= df["Район"] == q["loc"]["value"]
    else:
        m &= df["Адрес"].str.startswith(q["loc"]["value"] + ",")
    if "prefix" in q:
        m &= df["Наименование товара"].str.startswith(q["prefix"])
    else:
        m &= df["Наименование товара"] == q["name"]
    k = q["kind"]
    if k != "delta":
        m &= df["type"] == q["op"]
    d = df[m]
    if k == "mass":
        d = d[d["Ед_изм"] == "г"]
        return (d["packs"] * d["Количество в упаковке"]).sum() / 1000
    if k == "revenue":
        return (d["packs"] * d["Цена за упаковку"]).sum()
    if k == "packs":
        return d["packs"].sum()
    if k == "count_ops":
        return len(d)
    sign = d["type"].map({"Поступление": 1, "Продажа": -1})              # изменение запаса
    return (d["packs"] * sign).sum()


def theatre(path, q):
    sa = pd.read_excel(path, sheet_name="Продажи")
    pl = pd.read_excel(path, sheet_name="Спектакль")
    ta = pd.read_excel(path, sheet_name="Тариф")
    df = sa.merge(pl, on="ID спектакля").merge(ta, on="ID тарифа")
    df["Дата"] = pd.to_datetime(df["Дата"])
    m = (df["Дата"] >= q["d1"]) & (df["Дата"] <= q["d2"])
    if q.get("author"):
        m &= df["Автор"] == q["author"]
    if q.get("genre"):
        m &= df["Жанр"] == q["genre"]
    if q.get("cat"):
        m &= df["Категория зрителя"] == q["cat"]
    if q.get("benefit"):
        m &= df["Льгота"] == q["benefit"]
    d = df[m]
    if q["kind"] == "th_revenue":
        return (d["Количество билетов"] * d["Цена билета, руб."]).sum()
    return d["Количество билетов"].sum()


def family(path, q):
    pp = pd.read_excel(path, sheet_name="Люди")
    rl = pd.read_excel(path, sheet_name="Родственные связи")
    par = rl["ID ребёнка"].value_counts()
    kids = rl["ID родителя"].value_counts()
    k = q["kind"]
    if k == "one_parent":
        return (par == 1).sum()
    if k == "max_kids":
        return kids.max()
    if k == "grandkids":
        ch = rl[rl["ID родителя"] == q["pid"]]["ID ребёнка"]
        return rl["ID родителя"].isin(ch).sum()
    city = pp.set_index("ID")["Город рождения"]
    two = rl.groupby("ID ребёнка")["ID родителя"].apply(list)
    return sum(1 for v in two if len(v) == 2 and city[v[0]] == city[v[1]])


def main():
    path, qf = sys.argv[1], sys.argv[2]
    q = json.load(open(qf, encoding="utf-8"))
    if "d1" in q:
        q["d1"], q["d2"] = pd.Timestamp(q["d1"]), pd.Timestamp(q["d2"])
    r = {"sweets": sweets, "theatre": theatre, "family": family}[q["db"]](path, q)
    print(int(round(float(r))) if abs(float(r) - round(float(r))) < 1e-9 else r)


main()

